contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function check(uint256 e) public {
        require(address(this).balance >= e);
        address o = c.owner();
        uint256 ownerBefore = o.balance;

        // fund c with extra ether through its payable fallback
        (bool okFund, ) = address(c).call{value: e}("");
        require(okFund);

        // call go with zero value: P forwards only msg.value (0) to the target
        // and transfers the pre-existing balance to the owner;
        // M forwards the whole balance to the target and leaves 0 for the owner.
        c.go{value: 0}();

        assert(o.balance == ownerBefore + e);
    }
}

