contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // Precondition: the owner is a plain EOA distinct from this test contract,
        // so C's transfer to the owner can never fail.
        address ow = c.owner();
        require(ow != address(this));
        require(ow.code.length == 0);
        bool reverted;
        try c.go{value: amount}() { reverted = false; } catch { reverted = true; }
        // P always forwards leftovers to the EOA owner and completes.
        // M instead transfers to msg.sender (this contract, which has no
        // receive/fallback), so any transfer - even of zero value - fails.
        assert(!reverted);
    }
}

